/**
 * Official Authentic Social Media and Footer Icons (512x512 high resolution)
 * Embedded as Data URIs to guarantee 100% offline reliability in Android WebViews,
 * canvas rendering, and web production without network or path-resolution failures.
 */

export const SOCIAL_ICONS_DATA: Record<string, string> = {
  facebook: 'data:image/png;base64,',
  instagram: 'data:image/png;base64,',
  linkedin: 'data:image/png;base64,',
  x: 'data:image/png;base64,',
  twitter: 'data:image/png;base64,',
  youtube: 'data:image/png;base64,',
  whatsapp: 'data:image/png;base64,',
  website: 'data:image/png;base64,',
};

export const getSocialIconSrc = (platform: string): string => {
  const key = platform.toLowerCase().trim();
  if (key === 'twitter' || key === 'x') {
    return SOCIAL_ICONS_DATA.x || SOCIAL_ICONS_DATA.twitter;
  }
  return SOCIAL_ICONS_DATA[key] || `/assets/icons/${key}.png`;
};
